# Import of required libraries
import skyramp
import json
import os
import time


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")

# A recipe write must carry the whole recipe body, so each write below starts from
# the recipe as the API last returned it and replaces only its notes.
NOTE_AT_LIMIT = {"title": "At limit", "text": "a" * 255}
NOTE_OVER_LIMIT = {"title": "Too long", "text": "a" * 256}

def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    # Declaration of variables
    recipe_name = skyramp.unique_suffix("skyramp bulk note limit")

    # Request Body
    recipes_POST_request_body = r'''{
        "name": "skyramp bulk note limit"
    }'''

    # Execute Request
    recipes_POST_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes",
        method="POST",
        body=recipes_POST_request_body,
        headers=headers,
        data_override={"name": recipe_name}
    )

    # Generated Assertions
    assert recipes_POST_response.status_code == 201
    # the create response is the new recipe's slug, as a bare JSON string
    recipes = json.loads(recipes_POST_response.response_body)
    assert isinstance(recipes, str) and recipes != ""
    assert recipes.startswith("skyramp-bulk-note-limit")

    # Execute Request
    recipes_recipes_GET_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="GET",
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_GET_response.status_code == 200
    assert json.loads(recipes_recipes_GET_response.response_body)["slug"] == recipes
    assert skyramp.get_response_value(recipes_recipes_GET_response, "name") == recipe_name
    assert len(skyramp.get_response_value(recipes_recipes_GET_response, "notes")) == 0
    assert skyramp.get_response_value(recipes_recipes_GET_response, "notes.0") is None

    # Request Body: the recipe exactly as read back, with one note of 255 characters
    recipe_at_limit = json.loads(recipes_recipes_GET_response.response_body)
    recipe_at_limit["notes"] = [NOTE_AT_LIMIT]
    recipes_recipes_PUT_request_body = json.dumps(recipe_at_limit)

    # Execute Request
    recipes_recipes_PUT_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="PUT",
        body=recipes_recipes_PUT_request_body,
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_PUT_response.status_code == 200
    assert len(skyramp.get_response_value(recipes_recipes_PUT_response, "notes")) == 1
    assert skyramp.get_response_value(recipes_recipes_PUT_response, "notes.0.title") == "At limit"
    assert skyramp.get_response_value(recipes_recipes_PUT_response, "notes.0.text") == "a" * 255
    assert len(skyramp.get_response_value(recipes_recipes_PUT_response, "notes.0.text")) == 255
    assert skyramp.get_response_value(recipes_recipes_PUT_response, "notes.1") is None

    # Request Body: the stored recipe with a second note of 256 characters
    recipe_over_limit = json.loads(recipes_recipes_PUT_response.response_body)
    recipe_over_limit["notes"] = [NOTE_AT_LIMIT, NOTE_OVER_LIMIT]
    recipes_PUT_request_body = json.dumps([recipe_over_limit])

    # Execute Request
    recipes_PUT_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes",
        method="PUT",
        body=recipes_PUT_request_body,
        headers=headers
    )

    # Generated Assertions
    assert recipes_PUT_response.status_code == 422
    assert skyramp.get_response_value(recipes_PUT_response, "detail.0.type") == "string_too_long"
    assert skyramp.get_response_value(recipes_PUT_response, "detail.0.msg") == "String should have at most 255 characters"
    assert skyramp.get_response_value(recipes_PUT_response, "detail.0.loc") == ["body", 0, "notes", 1, "text"]
    assert skyramp.get_response_value(recipes_PUT_response, "detail.1") is None

    # Request Body: the same over-limit payload on the other bulk path
    recipes_PATCH_request_body = json.dumps([recipe_over_limit])

    # Execute Request
    recipes_PATCH_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes",
        method="PATCH",
        body=recipes_PATCH_request_body,
        headers=headers
    )

    # Generated Assertions
    assert recipes_PATCH_response.status_code == 422
    assert skyramp.get_response_value(recipes_PATCH_response, "detail.0.type") == "string_too_long"
    assert skyramp.get_response_value(recipes_PATCH_response, "detail.0.msg") == "String should have at most 255 characters"
    assert skyramp.get_response_value(recipes_PATCH_response, "detail.0.loc") == ["body", 0, "notes", 1, "text"]
    assert skyramp.get_response_value(recipes_PATCH_response, "detail.1") is None

    # Execute Request
    recipes_recipes_GET_1_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="GET",
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_GET_1_response.status_code == 200
    assert len(skyramp.get_response_value(recipes_recipes_GET_1_response, "notes")) == 1
    assert skyramp.get_response_value(recipes_recipes_GET_1_response, "notes.0.title") == "At limit"
    assert skyramp.get_response_value(recipes_recipes_GET_1_response, "notes.0.text") == "a" * 255
    assert skyramp.get_response_value(recipes_recipes_GET_1_response, "notes.1") is None
    assert skyramp.get_response_value(recipes_recipes_GET_1_response, "slug") == recipes

    # Execute Request
    recipes_recipes_DELETE_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="DELETE",
        headers=headers,
        path_params={"recipes": recipes}
    )

